{
  "rubric": {
    "title": "Software Engineer Performance Review Rubric",
    "version": "1.0",
    "description": "A structured rubric for evaluating software engineers across technical, delivery, collaboration, and impact dimensions.",
    "rating_scale": {
      "1": "Below Expectations",
      "2": "Partially Meets Expectations",
      "3": "Meets Expectations",
      "4": "Exceeds Expectations",
      "5": "Outstanding"
    },
    "rating_definitions": {
      "1": "Performance is consistently below the expectations for the role and level. Requires immediate improvement and close support.",
      "2": "Performance meets some expectations but has notable gaps. Requires targeted development and regular coaching.",
      "3": "Performance consistently meets the expectations for the role and level. Is a reliable contributor.",
      "4": "Performance frequently exceeds expectations. Delivers strong results and positively influences the team.",
      "5": "Performance is exceptional and sustained. Operates at a significantly higher level and elevates others."
    },
    "dimensions": [
      {
        "id": "technical_competence",
        "name": "Technical Competence",
        "weight": 0.18,
        "description": "Depth and breadth of technical knowledge, ability to apply it to real problems, and effectiveness with tools, languages, frameworks, and systems.",
        "criteria": {
          "1": {
            "label": "Below Expectations",
            "indicators": [
              "Struggles with core technologies required for assigned work.",
              "Needs frequent guidance to complete routine technical tasks.",
              "Technical decisions often introduce avoidable defects or rework."
            ]
          },
          "2": {
            "label": "Partially Meets Expectations",
            "indicators": [
              "Demonstrates basic knowledge but has gaps in key areas.",
              "Completes routine tasks with occasional guidance.",
              "Sometimes chooses suboptimal technical approaches."
            ]
          },
          "3": {
            "label": "Meets Expectations",
            "indicators": [
              "Applies required technical skills effectively to routine and moderately complex work.",
              "Produces sound technical solutions with limited guidance.",
              "Learns new technologies as needed to complete assignments."
            ]
          },
          "4": {
            "label": "Exceeds Expectations",
            "indicators": [
              "Demonstrates strong depth in one or more technical areas.",
              "Solves complex technical problems and improves existing systems.",
              "Shares technical knowledge and raises team capability."
            ]
          },
          "5": {
            "label": "Outstanding",
            "indicators": [
              "Recognized technical expert whose work defines best practices.",
              "Anticipates technical risks and designs scalable, durable solutions.",
              "Advances organizational technical strategy and mentors others at scale."
            ]
          }
        }
      },
      {
        "id": "code_quality_testing_maintainability",
        "name": "Code Quality, Testing, and Maintainability",
        "weight": 0.15,
        "description": "Quality of code, testing practices, documentation, review habits, and ability to keep systems maintainable and reliable.",
        "criteria": {
          "1": {
            "label": "Below Expectations",
            "indicators": [
              "Code is frequently difficult to read, test, or maintain.",
              "Tests are missing or inadequate for critical changes.",
              "Repeatedly ignores review feedback or quality standards."
            ]
          },
          "2": {
            "label": "Partially Meets Expectations",
            "indicators": [
              "Code is functional but inconsistent in style and clarity.",
              "Adds tests when prompted but coverage is uneven.",
              "Requires reminders to follow quality and review practices."
            ]
          },
          "3": {
            "label": "Meets Expectations",
            "indicators": [
              "Writes clear, maintainable code that follows team standards.",
              "Includes appropriate tests and documentation for changes.",
              "Gives and receives constructive code review feedback."
            ]
          },
          "4": {
            "label": "Exceeds Expectations",
            "indicators": [
              "Improves codebase health through refactoring and better patterns.",
              "Advances testing practices and reliability across the team.",
              "Provides high-quality reviews that improve design and reduce risk."
            ]
          },
          "5": {
            "label": "Outstanding",
            "indicators": [
              "Sets the standard for code quality, testing, and maintainability.",
              "Designs systems that are easy to operate, extend, and debug.",
              "Creates tools or practices adopted broadly to improve engineering quality."
            ]
          }
        }
      },
      {
        "id": "delivery_execution",
        "name": "Delivery and Execution",
        "weight": 0.15,
        "description": "Ability to plan, prioritize, and deliver work reliably, including estimation, risk management, and follow-through.",
        "criteria": {
