            "label": "Below Expectations",
            "indicators": [
              "Frequently misses commitments or delivers incomplete work.",
              "Poor prioritization leads to delays or wasted effort.",
              "Does not surface risks or blockers in time."
            ]
          },
          "2": {
            "label": "Partially Meets Expectations",
            "indicators": [
              "Delivers some commitments but with inconsistent reliability.",
              "Needs help to break down work and manage priorities.",
              "Sometimes fails to communicate progress or risks early."
            ]
          },
          "3": {
            "label": "Meets Expectations",
            "indicators": [
              "Delivers assigned work on time and with acceptable quality.",
              "Breaks down tasks, estimates reasonably, and tracks progress.",
              "Raises blockers and adjusts plans transparently."
            ]
          },
          "4": {
            "label": "Exceeds Expectations",
            "indicators": [
              "Consistently delivers complex work ahead of or on schedule.",
              "Anticipates dependencies and risks, keeping projects on track.",
              "Improves team delivery processes and predictability."
            ]
          },
          "5": {
            "label": "Outstanding",
            "indicators": [
              "Delivers high-impact outcomes reliably in ambiguous or high-pressure situations.",
