  "$id": "https://example.com/beta-cruiser.schema.json",
  "title": "beta cruiser",
  "description": "a schema for a beta cruiser vessel.",
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "the name of the beta cruiser, e.g. [beta_cruiser_name]",
      "default": "[beta_cruiser_name]"
    },
    "registry": {
      "type": "string",
      "pattern": "^[a-z0-9-]+$"
    },
    "class": {
      "type": "string",
      "enum": ["beta cruiser"]
    },
    "status": {
      "type": "string",
      "enum": ["active", "docked", "repair", "decommissioned"]
    },
    "crew_capacity": {
      "type": "integer",
      "minimum": 1
    },
    "max_speed": {
      "type": "number",
      "minimum": 0
    },
    "weapons": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "commissioned": {
      "type": "string",
      "format": "date"
    }
  },
  "required": ["name", "class", "status", "crew_capacity"]
}

