      "features": [
        "Search any restaurant to see average tip percentage, average dollar tip, and tip distribution.",
        "Filter by meal type, party size, daypart, payment method, and service style.",
        "Contribute a tip by uploading a receipt, syncing a card transaction, or manually entering it.",
        "View trends like weekend tipping patterns or counter-service averages.",
        "Restaurant dashboards show anonymized tip benchmarks without exposing individual payments."
      ]
    },
    "how_it_works": {
      "steps": [
        "User searches a restaurant or opens the app after a meal.",
        "Tipperary displays aggregate tip data with confidence scores and sample sizes.",
