      }
    },
    "business_model": {
      "revenue_streams": [
        {
          "stream": "Freemium consumer app",
          "detail": "Free basic tip lookup; premium unlocks advanced filters, alerts, and travel guides."
        },
        {
          "stream": "Restaurant SaaS",
          "detail": "Monthly subscription for tip benchmarking, shift insights, and competitor comparisons."
        },
        {
          "stream": "Data API",
          "detail": "Licensed, anonymized tipping trends for POS platforms, publishers, and market researchers."
        },
        {
          "stream": "Sponsored placements",
          "detail": "Ethical, clearly labeled restaurant recommendations and offers, never affecting tip data."
        }
      ]
    },
    "go_to_market": {
      "phase_1": "Launch in one dense metro with restaurant partnerships and receipt-upload incentives.",
      "phase_2": "Expand city by city using local food creators, hospitality worker communities, and viral tip comparisons.",
      "phase_3": "Add POS integrations and restaurant dashboards to create B2B stickiness.",
      "growth_loops": [
        "More users contribute data, which improves averages, which attracts more users who search and contribute.",
        "Restaurants share benchmark reports, which attracts more restaurants and enriches the data."
      ]
    },
    "competition": {
      "current_alternatives": [
        "Generic tipping guides and etiquette articles",
        "Credit card apps that show personal spending but not restaurant-level averages",
        "POS systems that hold tip data privately",
        "Reddit threads and anecdotal social posts"
      ],
      "differentiation": [
        "Restaurant-specific averages, not generic percentages",
        "Verified and fraud-resistant data pipeline",
        "Consumer utility plus B2B analytics",
        "Privacy-first aggregation with no individual transaction exposure"
      ]
    },
    "moat": [
      "Proprietary tipping dataset that improves with scale",
      "Network effects between diners, workers, and restaurants",
      "Restaurant integrations and verified profile claims",
      "Brand trust as the neutral standard for tipping transparency"
    ],
    "traction_and_roadmap": {
      "milestones": [
        "MVP with restaurant search and manual tip entry",
        "Receipt upload and fraud detection",
        "Restaurant claimed profiles and premium dashboards",
        "POS and API integrations",
        "Multi-city expansion"
      ],
      "success_metrics": [
        "Restaurants with statistically significant tip data",
        "Monthly active contributors",
        "Search-to-contribution conversion rate",
        "Restaurant SaaS retention"
      ]
    },
    "team": {
      "needs": [
        "Founder with hospitality or fintech experience",
        "Data engineer with privacy and fraud expertise",
        "Product designer focused on trust and simple UX",
        "Growth lead with local market launch experience"
      ]
    },
    "the_ask": {
      "raising": "$1.5M pre-seed",
      "use_of_funds": [
        "Build MVP and data pipeline",
        "Launch in first metro area",
        "Sign first 100 restaurant partners",
        "Prove contribution and retention loops"
      ]
    },
    "closing": "Tipperary turns tipping from guesswork into shared intelligence. When diners know the average tip, they tip with confidence; when restaurants see the benchmarks, they serve smarter."
  }
}

